'use strict';

const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  autoDetectInputDevice,
  createInputFromAutoDetect,
  createInputFromDetectedDevice,
  detectNanoKvmDevices,
  listDevices,
  probeInputDevice
} = require('..');

const execFileAsync = promisify(execFile);

async function getCursorPosFromSystem() {
  if (process.platform === 'darwin') {
    const { stdout } = await execFileAsync('swift', [
      '-e',
      [
        'import AppKit',
        'let p = NSEvent.mouseLocation',
        'let frame = NSScreen.screens.first?.frame ?? .zero',
        'print("\\(Int(p.x)),\\(Int(frame.height - p.y))")'
      ].join('\n')
    ]);
    const [x, y] = stdout.trim().split(',').map((value) => Number(value));
    if (Number.isFinite(x) && Number.isFinite(y)) {
      return { x, y };
    }
  }

  if (process.platform === 'win32') {
    const command = [
      'Add-Type -AssemblyName System.Windows.Forms',
      '$p = [System.Windows.Forms.Cursor]::Position',
      'Write-Output "$($p.X),$($p.Y)"'
    ].join('; ');
    const { stdout } = await execFileAsync('powershell.exe', ['-NoProfile', '-Command', command]);
    const [x, y] = stdout.trim().split(',').map((value) => Number(value));
    if (Number.isFinite(x) && Number.isFinite(y)) {
      return { x, y };
    }
  }

  throw new Error(`smoke move is not supported on platform ${process.platform}`);
}

async function main() {
  const [, , command = 'list', ...args] = process.argv;
  const portPath = process.env.NANOKVM_PORT || '';
  let input = null;

  async function getInput() {
    if (input) {
      return input;
    }
    if (portPath) {
      const detection = await probeInputDevice(portPath);
      input = createInputFromDetectedDevice(detection);
      return input;
    }
    const created = await createInputFromAutoDetect();
    console.log(JSON.stringify(created.detection, null, 2));
    input = created.input;
    return input;
  }

  if (command === 'list') {
    const devices = await listDevices();
    console.log(JSON.stringify(devices, null, 2));
    return;
  }

  if (command === 'detect') {
    const devices = await detectNanoKvmDevices();
    console.log(JSON.stringify(devices, null, 2));
    return;
  }

  if (command === 'probe') {
    const targetPortPath = args[0] || portPath;
    const kind = args[1] || process.env.THIFLOW_ROBOT_KIND || process.env.NANOKVM_KIND || '';
    const result = await probeInputDevice(
      kind === 'wyhkm' ? Number(targetPortPath || 0) : targetPortPath,
      kind ? { kind } : {}
    );
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  if (command === 'auto-detect') {
    const result = await autoDetectInputDevice();
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  if (command === 'health') {
    const targetInput = await getInput();
    try {
      await targetInput.connect();
    } catch (error) {
      console.error('[smoke:health] connect failed:', error?.message || error);
    }
    const health = await targetInput.getHealth();
    console.log(JSON.stringify(health, null, 2));
    await targetInput.disconnect();
    return;
  }

  if (command === 'click') {
    const targetInput = await getInput();
    await targetInput.connect();
    await targetInput.click('left');
    await targetInput.disconnect();
    console.log('[smoke:click] ok');
    return;
  }

  if (command === 'move') {
    const targetX = Number(args[0]);
    const targetY = Number(args[1]);
    if (!Number.isFinite(targetX) || !Number.isFinite(targetY)) {
      throw new Error('usage: node demos/smoke.js move <targetX> <targetY>');
    }
    const targetInput = await getInput();
    await targetInput.connect();
    await targetInput.moveTo(targetX, targetY, getCursorPosFromSystem);
    await targetInput.disconnect();
    console.log(`[smoke:move] ${targetX},${targetY} ok`);
    return;
  }

  if (command === 'paste') {
    const platform = args[0] || process.platform;
    const targetInput = await getInput();
    await targetInput.connect();
    await targetInput.pasteShortcut(platform);
    await targetInput.disconnect();
    console.log(`[smoke:paste] ${platform} ok`);
    return;
  }

  if (command === 'key') {
    const key = args[0];
    if (!key) {
      throw new Error('usage: node demos/smoke.js key <key>');
    }
    const targetInput = await getInput();
    await targetInput.connect();
    await targetInput.keyTap(key);
    await targetInput.disconnect();
    console.log(`[smoke:key] ${key} ok`);
    return;
  }

  throw new Error(`Unknown smoke command: ${command}`);
}

main().catch((error) => {
  console.error('[smoke] failed:', error);
  process.exitCode = 1;
});
